do $$
declare starter jsonb; candidate uuid; second uuid; creator uuid;
begin
 for starter in select value from test_starters,jsonb_array_elements(content) loop
   candidate := public.prepare_starter_draft('00000000-0000-0000-0000-000000000401',starter);
   update public.stories set hook='Founder edit',slug='edited-' || slug where cluster_id=candidate;
   second := public.prepare_starter_draft('00000000-0000-0000-0000-000000000401',starter);
   if candidate <> second or not exists(select 1 from public.stories where cluster_id=candidate and hook='Founder edit' and lifecycle='reviewing' and published_at is null) then raise exception 'Starter idempotence overwrote editorial work'; end if;
   if (select count(*) from public.cluster_signals where cluster_id=candidate) <> 2 then raise exception 'Starter receipts missing'; end if;
 end loop;
 if (select count(*) from public.stories where starter_key is not null) <> 7 then raise exception 'Expected seven real starter drafts'; end if;
 creator := public.register_manual_creator('https://instagram.com/artist','Artist','instagram.com');
 if creator <> public.register_manual_creator('https://instagram.com/artist','Rename','instagram.com') then raise exception 'Creator identity duplicated'; end if;
 if not exists(select 1 from public.source_definitions where id=creator and trust_tier='watchlist' and not active and not allowlisted) then raise exception 'Creator trust promoted'; end if;
 if has_function_privilege('authenticated','public.prepare_starter_draft(uuid,jsonb)','execute') then raise exception 'Starter RPC publicly accessible'; end if;
 -- The next automatic cycle must retain all saved drafts even when observations age.
 update public.raw_signals set observed_at=now()-interval '10 days';
 -- The first-observation trigger intentionally prevents this fixture update.
end;
$$;
alter table public.raw_signals disable trigger raw_signal_first_observation;
update public.raw_signals set observed_at=now()-interval '10 days';
alter table public.raw_signals enable trigger raw_signal_first_observation;
select public.process_unclustered_signals();
do $$ begin
 if (select count(*) from public.topic_clusters where state='reviewing') <> 7 then raise exception 'Automatic expiry removed founder drafts'; end if;
end; $$;
